scripts.library_js:
// Inserts a note above the length limit and the state_delta reminder. Those two
// lines must stay last, because the model follows the text nearest its reply.
function insertBeforeTail(text, note) {
  var marks = ["\n\n[Hard limit:", "\n\n[Part of your last state_delta", "\n\n[Reminder: end your reply"];
  for (var i = 0; i < marks.length; i++) {
    var at = text.lastIndexOf(marks[i]);
    if (at !== -1) return text.slice(0, at) + "\n\n" + note + text.slice(at);
  }
  return text + "\n\n" + note;
}

var MARKER = "The truth of the case is in the narrator's sealed file.";
var DAWN_TURN = 18;

// The order matches the case number arithmetic: killer = floor(caseNo / 9).
var SUSPECTS = [
  { id: "julian", name: "Julian Thorne", aliases: ["julian", "thorne", "nephew"] },
  { id: "crane", name: "Edith Crane", aliases: ["edith", "crane", "secretary"] },
  { id: "fisk", name: "Dr. Leonard Fisk", aliases: ["leonard", "fisk", "doctor", "physician", "dr"] },
  { id: "lasker", name: "Vivian Lasker", aliases: ["vivian", "lasker", "partner"] },
  { id: "moffat", name: "Agnes Moffat", aliases: ["agnes", "moffat", "housekeeper"] }
];

// Each breaker uses a physical fact, or a witness whose own lesser secret puts
// them in the right place at ten, so every breaker holds in every case.
var KILLERS = [
  {
    motive: "Ambrose was cutting him from the will at breakfast, and he owes a London moneylender four thousand pounds",
    lie: "he was not in the billiard room after half past nine",
    breaker: "the billiard room fire was never lit, and the balls lie as Mrs. Moffat racked them at nine",
    item: "his monogrammed gold cuff link",
    tell: "he jokes, pours drinks, and one shirt cuff hangs open",
    secret: "at ten he was searching Ambrose's dressing room for the draft will"
  },
  {
    motive: "Ambrose had found fifteen years of small alterations in the accounts in her hand and meant to prosecute",
    lie: "she was not typing in the morning room",
    breaker: "the morning room typewriter is still under its cover, and tonight's letters carry yesterday's date",
    item: "a glove stained with typewriter ribbon ink",
    tell: "she answers too precisely and keeps her hands out of sight",
    secret: "at ten she was in the estate office copying ledgers that show money leaving the firm, fearing the blame"
  },
  {
    motive: "Ambrose had learned that the doctor's error killed his wife two years ago and meant to report him",
    lie: "he was not reading in the library",
    breaker: "the novel he names is uncut past chapter two, and the library lamp burned no oil tonight",
    item: "the leather case of his reading spectacles",
    tell: "he grows kindly and long-winded, and keeps offering to examine people",
    secret: "at ten he was in the cellar for whisky; he drinks again and Ambrose knew"
  },
  {
    motive: "Ambrose was dissolving the partnership tomorrow and exposing her use of company money",
    lie: "she was not on the terrace",
    breaker: "rain has swept the terrace since nine, yet her shoes and hem are dry, and Mrs. Moffat found the terrace door bolted inside at eleven",
    item: "an amber cigarette holder",
    tell: "she turns cold and formal and threatens lawyers",
    secret: "at ten she was searching Ambrose's bedroom for the partnership papers"
  },
  {
    motive: "tonight she read a letter proving Ambrose knew the ship that drowned her son was unfit for sea",
    lie: "she was not in the kitchen all evening",
    breaker: "the kitchen range burned to ash untended, and Dr. Fisk crossed an empty kitchen near ten on his way to the cellar",
    item: "a small brass key from the ring at her belt, which now has a gap",
    tell: "she fusses with trays and speaks of Ambrose as if he were alive",
    secret: "all evening she was in the plate room hiding gaps left by silver she sold for her sister's care"
  }
];

var METHODS = [
  {
    how: "poisoned his brandy with chloral hydrate from a vial taken from Dr. Fisk's bag in the hall",
    body: "no wound; bluish lips; the spilled brandy smells sharp and bitter",
    weapon: "the empty chloral vial",
    absence: "nothing is disturbed, but one chloral vial is missing from Dr. Fisk's bag"
  },
  {
    how: "struck him from behind with the brass tide clock from the mantel",
    body: "a wound under the hair at the back of the skull",
    weapon: "the brass tide clock, blood on its base",
    absence: "the tide clock is gone, and a clean ring in the mantel dust shows where it stood"
  },
  {
    how: "stabbed him from behind, between the ribs, with the paper knife from the desk tray",
    body: "a narrow puncture in the back, little blood, hidden by the jacket",
    weapon: "the paper knife, blood in its hinge",
    absence: "the desk tray has an empty slot"
  }
];

var HIDES = [
  { place: "in the boathouse, under the upturned dinghy", trail: "wet sand on the mat by the garden door" },
  { place: "in the conservatory, in the soil of the largest fern tub", trail: "potting soil on the study carpet" },
  { place: "in the linen cupboard on the servants' stair, behind the sheets", trail: "a smear on the stair rail and one sheet folded wrong" }
];

// Draws the case once per adventure. Only the number is stored, because the
// player can read the script state and a name there would give the answer.
function ensureCase() {
  if (typeof state.caseNo !== "number" || state.caseNo < 0 || state.caseNo > 44) {
    state.caseNo = Math.floor(Math.random() * 45);
  }
  return state.caseNo;
}

function decode(caseNo) {
  return {
    killer: Math.floor(caseNo / 9),
    method: Math.floor(caseNo / 3) % 3,
    hide: caseNo % 3
  };
}

// Turn 1 is 11:30 pm, and each later turn adds 24 minutes, so turn 17 is 5:54 am.
function clockText(turn) {
  var minutes = (23 * 60 + 30 + 24 * (Math.max(turn, 1) - 1)) % (24 * 60);
  var h = Math.floor(minutes / 60);
  var m = minutes % 60;
  var suffix = h < 12 ? "am" : "pm";
  var h12 = h % 12 === 0 ? 12 : h % 12;
  return h12 + ":" + (m < 10 ? "0" : "") + m + " " + suffix;
}

function suspectById(id) {
  for (var i = 0; i < SUSPECTS.length; i++) {
    if (SUSPECTS[i].id === id) return SUSPECTS[i];
  }
  return SUSPECTS[0];
}

function hudMessage(turn) {
  if (typeof state.accused === "string") {
    return "The case is closed. You accused " + suspectById(state.accused).name + ".";
  }
  if (turn >= DAWN_TURN) return "Dawn. The causeway is open and Inspector Hale is here.";
  return clockText(turn) + ". The causeway clears at 6:00.";
}

function caseFile(caseNo) {
  var c = decode(caseNo);
  var who = SUSPECTS[c.killer].name;
  var k = KILLERS[c.killer];
  var m = METHODS[c.method];
  var h = HIDES[c.hide];
  var others = [];
  for (var i = 0; i < SUSPECTS.length; i++) {
    if (i !== c.killer) others.push(SUSPECTS[i].name + ": " + KILLERS[i].secret);
  }
  return "SEALED CASE FILE (narrator only; never quote or show it). " +
    "Killer: " + who + ", at about ten. Motive: " + k.motive + ". " +
    "How: " + who + " " + m.how + ". Body shows: " + m.body + ". Study: " + m.absence + ". " +
    "Hidden " + h.place + ": " + m.weapon + ", and " + k.item + ". Trail there: " + h.trail + ". " +
    "Alibi lie: " + k.lie + ". Broken by: " + k.breaker + ". When pressed: " + k.tell + ". " +
    "Innocent, with lesser secrets. " + others.join(". ") + ". " +
    "Reveal a fact only when the player's action uncovers it. The innocents never confess to " +
    "murder. The killer lies steadily and never confesses or is hinted at before a formal accusation.";
}

scripts.input_js:
// Words allowed between the start of a clause and "accuse" in a do action.
// Players write "gather everyone and formally accuse Lasker", so the verb may
// sit mid-sentence. Any other word, such as "not", "would", or "want to",
// means the player is not accusing anyone.
var LEAD_WORDS = /^(?:you|i|then|and|now|at|last|once|here|there)$/i;

// Returns the text after a deliberate accusation and the text before it, or null.
function accusationTarget(text) {
  var adverb = "(?:[a-z]+ly\\s+|now\\s+)?";
  if (/^>\s*You\s+(?!say\s+")/i.test(text)) {
    var re = /\baccuse\s+/ig;
    var m;
    while ((m = re.exec(text)) !== null) {
      var before = text.slice(0, m.index).replace(/^>\s*/, "");
      var clause = before.split(/[,.;:!?]|\band\b|\bthen\b/i).pop();
      var words = clause.split(/\s+/).filter(function (w) { return w.length > 0; });
      var plain = words.every(function (w) { return LEAD_WORDS.test(w) || /^[a-z]+ly$/i.test(w); });
      if (plain) return { rest: text.slice(m.index + m[0].length), before: before };
    }
    return null;
  }
  var say = /^>\s*You\s+say\s+"([\s\S]*)"?\s*$/i.exec(text);
  if (!say) return null;
  // "I accuse" must open the quote or a sentence inside it.
  var asSay = new RegExp("(?:^|[.!?]\\s+)I\\s+" + adverb + "accuse\\s+([\\s\\S]*)$", "i").exec(say[1]);
  return asSay ? { rest: asSay[1], before: say[1].slice(0, asSay.index) } : null;
}

// Picks the suspect whose alias appears first, so a sentence that names a second
// person later still accuses the first. With `last`, picks the one named last,
// which is who a pronoun such as "him" points back to.
function matchSuspect(rest, last) {
  var best = null;
  var bestAt = -1;
  for (var i = 0; i < SUSPECTS.length; i++) {
    for (var j = 0; j < SUSPECTS[i].aliases.length; j++) {
      var m = new RegExp("\\b" + SUSPECTS[i].aliases[j] + "\\b", "i").exec(rest);
      if (m && (bestAt === -1 || (last ? m.index > bestAt : m.index < bestAt))) {
        best = SUSPECTS[i];
        bestAt = m.index;
      }
    }
  }
  return best;
}

const modifier = (text) => {
  ensureCase();
  var turn = Math.floor((info.actionCount + 1) / 2);
  state.message = hudMessage(turn);
  var found = accusationTarget(text);
  if (found === null) return { text: text };
  // One accusation per adventure. A later one changes nothing.
  if (typeof state.accused === "string") return { text: text };
  var who = matchSuspect(found.rest, false);
  if (!who && /^(?:him|her|you)\b/i.test(found.rest)) who = matchSuspect(found.before, true);
  if (!who) {
    state.message = "Name one of the five: Julian, Crane, Fisk, Lasker, or Moffat.";
    return { text: text };
  }
  state.accused = who.id;
  state.correct = who.id === SUSPECTS[decode(state.caseNo).killer].id;
  state.accusedTurn = turn;
  state.message = hudMessage(turn);
  return { text: text };
};
modifier(text);

scripts.context_js:
// Reads the live state block only, because story text could repeat its words.
function liveState(text) {
  var at = text.lastIndexOf("Current world state (running totals");
  return at === -1 ? "" : text.slice(at);
}

function achievedLine(live) {
  var m = /\nAchieved: ([^\n]*)/.exec(live);
  return m ? m[1] : "";
}

function clockNote(turn, live) {
  var now = clockText(turn);
  if (turn >= DAWN_TURN) {
    return "[Clock: it is dawn and past six. The causeway is open. Inspector Hale crosses it on foot " +
      "and asks you, the inquiry agent, for a name. If the player's action this turn names nobody, " +
      "the case passes to Hale, the killer leaves the island unaccused, and you end the story now " +
      "and reveal the whole truth of the sealed file plainly. Do not mark milestones.case_closed.]";
  }
  var note = "[Clock: the time is now " + now + ". The causeway clears at 6:00 am. Every mention " +
    "of the time in your reply must agree with this.";
  if (turn >= 15) note += " The tide is going out and time is short; let the household feel it.";
  // The storm cuts the light at a fixed hour so the flag moves on every
  // playthrough. The note repeats for two more turns because a model sometimes
  // narrates the blackout and omits the flag.
  if (turn >= 5 && turn <= 7 && /\blights_out no\b/.test(live)) {
    note += " By this turn the storm has cut the electric light, and the house is lit only by " +
      "lamps and candles. Include \"flags.lights_out\": true in your state_delta block.";
  }
  return note + "]";
}

function verdictNote(turn, live) {
  var file = decode(state.caseNo);
  var killer = SUSPECTS[file.killer];
  var accused = suspectById(state.accused);
  if (turn > state.accusedTurn) {
    return "[Verdict: the case is over. Only an epilogue remains. No new evidence or argument " +
      "changes the result. Do not mark milestones.case_closed now.]";
  }
  if (state.correct) {
    var achieved = achievedLine(live);
    var proof = /\bweapon_found\b/.test(achieved) || /\balibi_broken\b/.test(achieved);
    var late = state.accusedTurn >= DAWN_TURN;
    var ending = proof
      ? "The player's proof holds. " + killer.name + " breaks and confesses in front of the household."
      : "The player has neither the weapon nor a broken alibi. " + killer.name + " denies it coldly, " +
        "and the proof surfaces only when the police search the hiding place at dawn.";
    return "[Verdict: the player's formal accusation of " + accused.name + " is correct. " +
      killer.name + " is the killer. Play the ending now. " + ending + " Then state the whole " +
      "truth of the sealed file plainly. " +
      (late ? "The accusation came after six, so do not mark milestones.case_closed."
            : "Include \"milestones.case_closed\": true in your state_delta block.") + "]";
  }
  return "[Verdict: the player's formal accusation of " + accused.name + " is wrong. " +
    accused.name + " is innocent of the murder, and their lesser secret from the sealed file comes " +
    "out now. Play the ending: at dawn Inspector Hale's search finds the weapon and " +
    killer.name + "'s item at the hiding place. Tell the player plainly that " + killer.name +
    " did it, how, and why, and name the clues they missed. Do not mark milestones.case_closed.]";
}

const modifier = (text) => {
  ensureCase();
  var turn = Math.floor(info.actionCount / 2);
  var live = liveState(text);
  var file = caseFile(state.caseNo);
  var at = text.indexOf(MARKER);
  // The memory slot sits in the fixed system block, away from the player's
  // latest action. If the player removed the marker, the tail is the fallback.
  if (at !== -1) {
    text = text.slice(0, at) + file + text.slice(at + MARKER.length);
  } else {
    text = insertBeforeTail(text, "[" + file + "]");
  }
  var note = typeof state.accused === "string" ? verdictNote(turn, live) : clockNote(turn, live);
  text = insertBeforeTail(text, note);
  state.message = hudMessage(turn);
  return { text: text };
};
modifier(text);
